<?php
const ACTIVE="('Pending','Confirmed','Checked-In')";
function out($d,$c=200){throw new \Illuminate\Http\Exceptions\HttpResponseException(response()->json($d,$c));}
function q($sql,$p=[]){return \App\Models\ResortData::query($sql,$p);}
function notify($uid,$title,$message,$type='booking',$rid=null){q("INSERT INTO notifications(user_id,title,message,notification_type,reservation_id) VALUES(?,?,?,?,?)",[$uid,$title,$message,$type,$rid]);}
function audit($action,$details){$u=$_SESSION['u']??null;if($u&&$u['user_role']=='Admin')q("INSERT INTO admin_activity(user_id,action,details) VALUES(?,?,?)",[$u['user_id'],$action,clean($details,500)]);}
function userPhotoColumn(){static $col=null;if($col!==null)return $col;$cols=q("SHOW COLUMNS FROM users")->fetchAll();$names=array_column($cols,'Field');if(in_array('profile_photo',$names,true))return $col='profile_photo';if(in_array('photo',$names,true))return $col='photo';out(['error'=>'Profile photo column is missing. Run profile_update.sql.'],500);}
function need(...$r){$u=$_SESSION['u']??null;if(!$u||($r&&!in_array($u['user_role'],$r)))out(['error'=>'Not allowed'],403);if($u['user_role']=='Guest'&&!q("SELECT is_active FROM users WHERE user_id=?",[$u['user_id']])->fetchColumn()){session_destroy();out(['error'=>'This account is inactive. Contact the resort administrator.'],403);}return $u;}
function clean($s,$n=100){return mb_substr(trim(strip_tags((string)$s)),0,$n);}
function checkoutOverdue($date){static $checkoutTime=null;if($checkoutTime===null){$checkoutTime=q("SELECT setting_value FROM resort_settings WHERE setting_key='check_out_time'")->fetchColumn();if(!$checkoutTime)$checkoutTime='12:00';}$zone=new DateTimeZone('Asia/Manila');try{$deadline=new DateTimeImmutable($date.' '.$checkoutTime,$zone);return new DateTimeImmutable('now',$zone)>$deadline;}catch(Throwable $e){return false;}}
function smtpReply($sock){$r='';while(($line=fgets($sock,515))!==false){$r.=$line;if(strlen($line)<4||$line[3]===' ')break;}return $r;}
function smtpCommand($sock,$command,$expected){if($command!==null)fwrite($sock,$command."\r\n");$reply=smtpReply($sock);if(!preg_match('/^(\d{3})/',$reply,$m)||!in_array((int)$m[1],(array)$expected,true))throw new RuntimeException('SMTP rejected command: '.trim($reply));return $reply;}
function sendEmail($to,$subject,$html){global $MAIL;$host=trim($MAIL['host']??'');$from=trim($MAIL['from_email']??'');$username=trim($MAIL['username']??'');$password=trim($MAIL['password']??'');if(!$host||!$from||!$username||!$password){error_log('MNB mail is not configured: SMTP host, username, password, and sender are required.');return false;}$port=(int)($MAIL['port']??587);$enc=strtolower($MAIL['encryption']??'tls');$target=($enc==='ssl'?'ssl://':'').$host;$errno=0;$err='';$sock=@stream_socket_client($target.':'.$port,$errno,$err,12,STREAM_CLIENT_CONNECT);if(!$sock){error_log('MNB mail SMTP connection failed: '.$err.' ('.$errno.').');return false;}stream_set_timeout($sock,12);try{smtpCommand($sock,null,220);smtpCommand($sock,'EHLO mnb-resort.local',250);if($enc==='tls'){smtpCommand($sock,'STARTTLS',220);if(!stream_socket_enable_crypto($sock,true,STREAM_CRYPTO_METHOD_TLS_CLIENT))throw new RuntimeException('SMTP TLS negotiation failed');smtpCommand($sock,'EHLO mnb-resort.local',250);}if(!empty($MAIL['username'])){smtpCommand($sock,'AUTH LOGIN',334);smtpCommand($sock,base64_encode($MAIL['username']),334);smtpCommand($sock,base64_encode($MAIL['password']??''),235);}smtpCommand($sock,'MAIL FROM:<'.$from.'>',250);smtpCommand($sock,'RCPT TO:<'.$to.'>',[250,251]);smtpCommand($sock,'DATA',354);$fromName='=?UTF-8?B?'.base64_encode($MAIL['from_name']??'MNB Resort').'?=';$headers=['From: '.$fromName.' <'.$from.'>','To: <'.$to.'>','Subject: =?UTF-8?B?'.base64_encode($subject).'?=','MIME-Version: 1.0','Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: 8bit'];$body=implode("\r\n",$headers)."\r\n\r\n".preg_replace('/\r?\n/','\r\n',$html);$body=str_replace("\r\n.","\r\n..",$body);fwrite($sock,$body."\r\n.\r\n");smtpCommand($sock,null,250);smtpCommand($sock,'QUIT',221);fclose($sock);return true;}catch(Throwable $e){fclose($sock);error_log('MNB mail delivery failed: '.$e->getMessage());return false;}}
function issueOtp($email,$purpose,$userId=null,$name=null,$phone=null,$passwordHash=null){global $pdo;$recent=(int)q("SELECT COUNT(*) FROM email_otps WHERE email=? AND purpose=? AND created_at>=DATE_SUB(NOW(),INTERVAL 15 MINUTE)",[$email,$purpose])->fetchColumn();if($recent>=4)return 'Too many code requests. Please wait 15 minutes before trying again.';$expiresMinutes=$purpose==='register'?3:10;$code=(string)random_int(100000,999999);q("INSERT INTO email_otps(user_id,email,purpose,code_hash,full_name,phone,password_hash,expires_at) VALUES(?,?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL ".$expiresMinutes." MINUTE))",[$userId,$email,$purpose,password_hash($code,PASSWORD_DEFAULT),$name,$phone,$passwordHash]);$otpId=$pdo->lastInsertId();$purposeText=['register'=>'verify your email and finish creating your account','reset'=>'reset your password','password_change'=>'confirm your password change'][$purpose]??'verify your request';$html='<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;padding:28px;color:#20243a"><h2>MNB Resort</h2><p>Use this one-time code to '.$purposeText.':</p><div style="font-size:32px;font-weight:bold;letter-spacing:8px;padding:18px;background:#f1f2f8;border-radius:12px;text-align:center">'.$code.'</div><p>This code expires in '.$expiresMinutes.' minutes. If you did not request it, ignore this email.</p></div>';if(!sendEmail($email,'Your MNB Resort verification code',$html)){q("DELETE FROM email_otps WHERE otp_id=?",[$otpId]);return 'Email delivery is not configured or failed. Please contact the resort administrator.';}return null;}
function validateOtp($email,$purpose,$code){$row=q("SELECT * FROM email_otps WHERE email=? AND purpose=? ORDER BY otp_id DESC LIMIT 1",[$email,$purpose])->fetch();if(!$row||strtotime($row['expires_at'])<time())return ['error'=>'That code is invalid or expired. Request a new code.'];if((int)$row['attempts']>=5)return ['error'=>'Too many incorrect attempts. Request a new code.'];if(!password_verify((string)$code,$row['code_hash'])){q("UPDATE email_otps SET attempts=attempts+1 WHERE otp_id=?",[$row['otp_id']]);return ['error'=>'That code is incorrect.'];}return ['row'=>$row];}
function dt($s){$d=DateTime::createFromFormat('Y-m-d',(string)$s);return $d&&$d->format('Y-m-d')===$s;}
function free($room,$ci,$co,$ex=0){return q("SELECT COUNT(*) FROM reservations WHERE room_id=? AND reservation_id<>? AND status IN ".ACTIVE." AND check_in_date<? AND check_out_date>?",[$room,$ex,$co,$ci])->fetchColumn()==0;}
function savePhoto($id,$d){
 if(is_string($d))$d=$d===''?[]:[$d];
 if(!is_array($d)||count($d)>6)return'Choose up to 6 room photos.';
 if(!$d){q("UPDATE accommodations SET photo=NULL WHERE room_id=?",[$id]);return null;}
 $photos=[];$total=0;
 foreach($d as $image){
  if(!is_string($image)||!preg_match('#^data:image/(jpeg|png|webp);base64,(.+)$#s',$image,$m))return'Choose valid JPEG, PNG, or WebP room photos.';
  $b=base64_decode($m[2],true);if($b===false)return'One of the room photos has invalid image data.';
  $total+=strlen($b);if($total>4*1024*1024)return'The combined room photos must be under 4 MB.';
  $info=@getimagesizefromstring($b);if(!$info||!in_array($info['mime'],['image/jpeg','image/png','image/webp'],true)||$info['mime']!=='image/'.$m[1])return'One of the selected files is not a valid supported image.';
  $photos[]=$image;
 }
 $stored=json_encode($photos,JSON_UNESCAPED_SLASHES);if($stored===false)return'Could not prepare the room photos.';
 q("UPDATE accommodations SET photo=? WHERE room_id=?",[$stored,$id]);return null;
}
function loginAs($id){$u=q("SELECT user_id,full_name,user_role FROM users WHERE user_id=?",[$id])->fetch();session_regenerate_id(true);$_SESSION['u']=$u;out(['user'=>$u]);}
